{"path":"about.html","content":"<!DOCTYPE html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#6b4cff;--muted:#667085;--bg:#0f1724;--card:#0b1220;--glass:rgba(255,255,255,0.04);--soft:#e6eef8}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:#e6eef8;background:linear-gradient(180deg,#071023 0%, #07182a 60%);}
    .page{max-width:980px;margin:40px auto;padding:28px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:14px;box-shadow:0 8px 30px rgba(2,6,23,0.7);position:relative;overflow:hidden}
    .pattern{position:absolute;inset:0;opacity:.06;background-image:url('assets/img/pattern.svg');background-repeat:repeat;background-size:220px;mix-blend-mode:screen}
    header{display:flex;align-items:center;justify-content:space-between;position:relative;z-index:2}
    header h1{margin:0;font-size:20px;letter-spacing:0.6px}
    nav{display:flex;gap:12px}
    nav a{color:var(--soft);text-decoration:none;padding:8px 12px;border-radius:8px;font-size:13px}
    nav a.active{background:rgba(107,76,255,0.12);color:var(--accent)}

    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:28px 0}
    .tag{font-size:28px;font-weight:600;color:#fff}
    .sub{color:var(--muted);max-width:68ch}

    .row{display:flex;gap:20px;align-items:flex-start}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:18px;border-radius:12px;flex:1;border:1px solid rgba(255,255,255,0.03)}
    .muted{color:var(--muted);font-size:14px}

    .expect ul{padding-left:18px}
    .expect li{margin:8px 0}

    /* Proof Gallery */
    .proof{display:flex;flex-direction:column;gap:12px}
    .testimonial{min-height:84px;display:flex;flex-direction:column;justify-content:center}
    .quote{font-style:italic;color:#dfe9ff}
    .author{font-size:13px;color:var(--muted);margin-top:8px}
    .badges{display:flex;gap:8px;margin-top:12px}
    .badge{background:rgba(255,255,255,0.03);padding:8px 10px;border-radius:999px;font-size:12px;position:relative;cursor:default}
    .badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);white-space:nowrap;background:#0b1220;padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);font-size:12px;color:var(--soft)}

    .cta{margin-top:18px}
    .btn{background:var(--accent);color:white;padding:12px 16px;border-radius:10px;text-decoration:none;font-weight:600}

    footer{margin-top:28px;color:var(--muted);font-size:13px;display:flex;justify-content:space-between;align-items:center}

    @media (max-width:720px){.row{flex-direction:column}}
  </style>
</head>
<body>
  <div class='page'>
    <div class='pattern' aria-hidden='true'></div>
    <header>
      <h1>{{BUSINESS_NAME}}</h1>
      <nav>
        <a href='index.html'>Home</a>
        <a href='events.html'>Gatherings</a>
        <a href='private-sessions.html'>Private</a>
        <a href='pricing.html'>Rates</a>
        <a href='about.html' class='active'>About</a>
        <a href='faq.html'>FAQ</a>
        <a href='book.html'>Reserve</a>
        <a href='contact.html'>Connect</a>
      </nav>
    </header>

    <main>
      <section class='hero' aria-labelledby='about-heading'>
        <div>
          <div id='about-heading' class='tag'>A thoughtful pause in sound</div>
          <div class='sub'>{{TAGLINE}} — a place to arrive without rushing. We host small gatherings and individual sessions that use tuned instruments and gentle sequences to help you drop out of busy thinking and into steadier presence.</div>
        </div>
      </section>

      <div class='row'>
        <section class='card expect'>
          <h3>How a visit unfolds</h3>
          <p class='muted'>A concise flow so you know what to expect.</p>
          <ul>
            <li>Welcome & orientation — a calm start, 5–10 minutes.</li>
            <li>Settling phase with grounding tones and breath guidance.</li>
            <li>Active resonance portion: layered bowls, chimes, and subtle percussion.</li>
            <li>Gentle return and time to rehydrate and share impressions.</li>
          </ul>
          <p class='muted'>Sessions run 50–75 minutes depending on the offering. Wear comfortable clothes and bring a mat or blanket if you prefer.</p>
        </section>

        <aside class='card proof' aria-label='Proof Gallery'>
          <h3>Testimonials & trust</h3>
          <div id='testimonial' class='testimonial'>
            <div class='quote' id='quote'>"The evening left a calm I carried for days — clear and soft at once."</div>
            <div class='author' id='author'>— M., local educator</div>
          </div>

          <div class='badges' id='badges'>
            <div class='badge' data-tip='Featured by regional wellness journal'>Wellness Mag</div>
            <div class='badge' data-tip='Verified community-hosted gatherings'>Neighborhood Arts</div>
            <div class='badge' data-tip='Clinically informed safety practices'>Safety Review</div>
          </div>

          <div class='cta'>
            <a class='btn' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
            <div style='margin-top:8px;color:var(--muted);font-size:13px'>Or call <a href='tel:{{PHONE}}' style='color:var(--soft);text-decoration:none'>{{PHONE}}</a></div>
          </div>
        </aside>
      </div>

      <section style='margin-top:20px' class='card'>
        <h3>Health & safety</h3>
        <p class='muted'>We welcome most people but some conditions need extra care. Please consult with your provider or our team before reserving if any of the following apply:</p>
        <ul>
          <li>Epilepsy or seizure disorders.</li>
          <li>Pregnancy in the first trimester or any pregnancy with complications — check with your clinician.</li>
          <li>Implanted medical devices like pacemakers.</li>
          <li>Active severe psychiatric episodes or unmanaged psychosis.</li>
        </ul>
        <p class='muted'>If in doubt, contact us at <a href='mailto:{{EMAIL}}' style='color:var(--soft);text-decoration:none'>{{EMAIL}}</a> for guidance.</p>
      </section>

    </main>

    <footer>
      <div>Serving {{CITY}}, {{STATE}}</div>
      <div>Contact: <a href='mailto:{{EMAIL}}' style='color:var(--soft);text-decoration:none'>{{EMAIL}}</a> • <a href='tel:{{PHONE}}' style='color:var(--soft);text-decoration:none'>{{PHONE}}</a></div>
    </footer>
  </div>

  <script>
    // Rotating testimonials and badges
    (function(){
      const items = [
        {quote: 'I slept deeper the night after the session — a welcome reset.', author: 'K., designer', badges: ['Local Press','Community Vetted']},
        {quote: 'The tones were precise and kind; the room felt safe to unwind.', author: 'S., nurse', badges: ['Practitioner Endorsed','Safety Review']},
        {quote: 'A simple, powerful practice that fits into a busy week.', author: 'T., parent', badges: ['Wellness Mag','Neighborhood Arts']}
      ];
      const quoteEl = document.getElementById('quote');
      const authorEl = document.getElementById('author');
      const badgesEl = document.getElementById('badges');
      let i=0;
      function show(idx){
        const it = items[idx];
        quoteEl.textContent = '"' + it.quote + '"';
        authorEl.textContent = '— ' + it.author;
        // rebuild badges
        badgesEl.innerHTML = '';
        it.badges.forEach(b=>{
          const d = document.createElement('div');
          d.className = 'badge';
          d.textContent = b;
          d.setAttribute('data-tip', b + ' — click to learn more');
          badgesEl.appendChild(d);
        });
      }
      show(0);
      setInterval(()=>{ i = (i+1) % items.length; show(i); }, 4200);
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!DOCTYPE html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#061025;--muted:#98a0b3;--accent:#8a5bff}
    body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,Arial;background:linear-gradient(180deg,#04101b,#062033);color:#eaf0ff}
    .wrap{max-width:920px;margin:36px auto;padding:24px;background:rgba(255,255,255,0.02);border-radius:12px;position:relative}
    .pattern{position:absolute;inset:0;opacity:.05;background-image:url('assets/img/pattern.svg');background-repeat:repeat;background-size:200px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);margin-left:12px;text-decoration:none}
    .hero{margin-top:18px}
    h1{margin:0;font-size:22px}
    .lead{color:var(--muted);margin-top:8px}

    .faq{margin-top:18px}
    .q{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;margin-bottom:10px;cursor:pointer}
    .q h4{margin:0}
    .a{padding:10px 12px;color:var(--muted);display:none}
    .q.open .a{display:block}

    .proof{margin-top:18px;display:flex;gap:12px;align-items:center}
    .proof .msg{flex:1}
    .proof .badges{display:flex;gap:8px}
    .badge{background:rgba(255,255,255,0.03);padding:8px;border-radius:8px;font-size:13px}

    .cta{margin-top:18px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none}
  </style>
</head>
<body>
  <div class='wrap'>
    <div class='pattern' aria-hidden='true'></div>
    <header>
      <div>
        <h1>Questions, answered</h1>
        <div class='lead'>Short answers for common concerns — if you need more, reach out.</div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='events.html'>Gatherings</a>
        <a href='book.html'>Reserve</a>
        <a href='contact.html'>Connect</a>
      </nav>
    </header>

    <section class='faq' aria-label='Frequently asked questions'>
      <div class='q' data-key='1'>
        <h4>How long is a typical session?</h4>
        <div class='a'>Most group gatherings are around 60 minutes. Private sessions vary — usually 50 to 75 minutes depending on the format.</div>
      </div>

      <div class='q' data-key='2'>
        <h4>What should I bring?</h4>
        <div class='a'>A yoga mat or blanket, a pillow for support, water, and anything you need to feel comfortable. We provide mats on request where noted.</div>
      </div>

      <div class='q' data-key='3'>
        <h4>Can anyone attend?</h4>
        <div class='a'>Most people can join. If you have seizures, pacemakers, or are in an unstable psychiatric state please consult with us or your provider first. Pregnant participants should check with their clinician for comfort and timing.</div>
      </div>

      <div class='q' data-key='4'>
        <h4>How do I cancel or change a reservation?</h4>
        <div class='a'>Cancellations up to 48 hours before an event receive a full credit. After that, credits are discretionary and we may offer a transfer to another date when possible.</div>
      </div>
    </section>

    <section class='proof' aria-label='Testimonials preview'>
      <div class='msg'>
        <div id='faq-quote' style='font-style:italic'>"A steady, well-crafted experience — I left feeling like a clearer version of myself."</div>
        <div style='color:var(--muted);margin-top:6px' id='faq-author'>— R., therapist</div>
      </div>
      <div class='badges' id='faq-badges'>
        <div class='badge' data-tip='Community vetted hosts'>Community</div>
        <div class='badge' data-tip='Press mention'>Press</div>
      </div>
    </section>

    <div class='cta'>
      <a href='book.html' class='btn'>Reserve a seat</a>
      <span style='color:var(--muted);margin-left:12px'>Questions? Email <a href='mailto:{{EMAIL}}' style='color:inherit;text-decoration:underline'>{{EMAIL}}</a></span>
    </div>

    <footer style='margin-top:18px;color:var(--muted)'>Serving {{CITY}}, {{STATE}} • Phone: <a href='tel:{{PHONE}}' style='color:inherit;text-decoration:none'>{{PHONE}}</a></footer>
  </div>

  <script>
    // FAQ accordion
    document.querySelectorAll('.q').forEach(item=>{
      item.addEventListener('click',()=>{ item.classList.toggle('open'); });
    });

    // Small rotating proof for credibility
    (function(){
      const entries = [
        {q: 'An evening that settled my head and my back.', a: 'V., artist'},
        {q: 'Clear instructions and thoughtful pacing made this approachable.', a: 'H., student'},
        {q: 'I appreciate the safety-first approach and the care before and after the session.', a: 'B., clinician'}
      ];
      let idx = 0;
      const elQ = document.getElementById('faq-quote');
      const elA = document.getElementById('faq-author');
      const badges = [['Community','Press'],['Practitioner Endorsed','Community'],['Safety Review','Neighborhood Arts']];
      const badgesEl = document.getElementById('faq-badges');
      function show(i){
        elQ.textContent = '"' + entries[i].q + '"';
        elA.textContent = '— ' + entries[i].a;
        badgesEl.innerHTML = '';
        badges[i].forEach(t=>{ const d=document.createElement('div'); d.className='badge'; d.textContent=t; d.setAttribute('data-tip', t); badgesEl.appendChild(d); });
      }
      show(0);
      setInterval(()=>{ idx = (idx+1) % entries.length; show(idx); },3500);
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!DOCTYPE html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Book — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071026;--card:#081426;--accent:#6bffdf;--muted:#9fb0c8}
    body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,Arial;background:linear-gradient(180deg,#02101a,#041a2a);color:#e7fbff}
    .wrap{max-width:980px;margin:28px auto;padding:20px;border-radius:12px;position:relative}
    .pattern{position:absolute;inset:0;opacity:.045;background-image:url('assets/img/pattern.svg');background-repeat:repeat;background-size:210px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);margin-left:12px;text-decoration:none}

    .grid{display:grid;grid-template-columns:1fr 340px;gap:18px;margin-top:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    label{display:block;font-size:13px;margin-top:10px;color:var(--muted)}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:inherit}
    .row{display:flex;gap:8px}

    .mixer{display:flex;gap:8px;margin-top:12px}
    .mix-btn{padding:10px 14px;border-radius:999px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03);cursor:pointer}
    .mix-btn.active{background:linear-gradient(90deg,var(--accent),#8a5bff);color:#022;box-shadow:0 6px 20px rgba(107,255,223,0.07)}

    .recommend{margin-top:12px;padding:12px;border-radius:10px;background:rgba(255,255,255,0.02)}
    .price{font-weight:700;color:var(--accent)}

    .next{font-size:14px;color:var(--muted);margin-top:12px}
    .btn{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#022;border-radius:10px;text-decoration:none;font-weight:700}

    .disclaimer{margin-top:12px;color:var(--muted);font-size:13px}

    @media (max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class='wrap'>
    <div class='pattern' aria-hidden='true'></div>
    <header>
      <div>
        <h2 style='margin:0'>Reserve</h2>
        <div style='color:var(--muted);font-size:13px'>Choose a session and set your sound preference.</div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='events.html'>Gatherings</a>
        <a href='pricing.html'>Rates</a>
        <a href='contact.html'>Help</a>
      </nav>
    </header>

    <div class='grid'>
      <div>
        <form id='booking' class='card' onsubmit='return false;'>
          <label for='name'>Full name</label>
          <input id='name' name='name' required placeholder='Your name'>

          <label for='email'>Email</label>
          <input id='email' name='email' type='email' required placeholder='you@example.com'>

          <label for='phone'>Phone</label>
          <input id='phone' name='phone' placeholder='Optional'>

          <label for='program'>Select offering</label>
          <select id='program' name='program'>
            <option value='drift'>Evening Drift — 60 minutes</option>
            <option value='core'>Core Resonance — 75 minutes</option>
            <option value='immersion'>Immersion+ — 90 minutes</option>
          </select>

          <label>Sound preference</label>
          <div class='mixer' role='tablist' aria-label='Sound intensity selector'>
            <button type='button' class='mix-btn' data-level='gentle' id='level-gentle'>Gentle</button>
            <button type='button' class='mix-btn active' data-level='medium' id='level-medium'>Medium</button>
            <button type='button' class='mix-btn' data-level='intense' id='level-intense'>Intense</button>
          </div>

          <div id='recommend' class='recommend'>
            <div style='font-size:14px;color:var(--muted)'>Recommended program:</div>
            <div style='margin-top:6px;font-weight:600' id='rec-name'>Core Resonance</div>
            <div style='margin-top:6px' id='rec-desc'>A steady, layered session focused on full-body resonance and paced returns.</div>
            <div style='margin-top:8px'>Price: <span class='price' id='rec-price'>$35</span></div>
          </div>

          <label for='date'>Choose a date</label>
          <select id='date' name='date'></select>

          <div class='disclaimer'>
            Contraindications: If you have epilepsy, are in an unstable psychiatric state, have implanted electrical devices, or are pregnant with complications, speak to your clinician before booking. If unsure, contact <a href='mailto:{{EMAIL}}' style='color:inherit;text-decoration:underline'>{{EMAIL}}</a>.
          </div>

          <div style='display:flex;gap:10px;align-items:center'>
            <button id='submit' class='btn'>Request reservation</button>
            <a href='contact.html' style='color:var(--muted);text-decoration:underline;margin-left:6px'>Need help?</a>
          </div>
        </form>
      </div>

      <aside class='card'>
        <h4 style='margin:0'>Quick availability</h4>
        <div class='next' id='next-available'>Next opening: —</div>
        <ul id='calendar' style='margin-top:12px;color:var(--muted);padding-left:18px'></ul>

        <div style='margin-top:18px'>
          <h4 style='margin:0'>Pricing model</h4>
          <p class='muted' style='margin-top:8px'>Pay per drop-in, or buy a 3-visit credit pack for a discount. Private sessions priced individually — contact for details.</p>
        </div>

        <div style='margin-top:12px'>
          <strong style='color:var(--accent)'>Single visit</strong>: $35 · <strong style='color:var(--accent)'>3-pack</strong>: $95
        </div>
      </aside>
    </div>

    <footer style='margin-top:18px;color:var(--muted)'>Questions about accessibility or safety? Email <a href='mailto:{{EMAIL}}' style='color:inherit;text-decoration:underline'>{{EMAIL}}</a> or call <a href='tel:{{PHONE}}' style='color:inherit;text-decoration:none'>{{PHONE}}</a></footer>
  </div>

  <script>
    // Simple booking UI: mixer changes recommendation
    (function(){
      const mixBtns = Array.from(document.querySelectorAll('.mix-btn'));
      const recName = document.getElementById('rec-name');
      const recDesc = document.getElementById('rec-desc');
      const recPrice = document.getElementById('rec-price');
      const programEl = document.getElementById('program');

      const profiles = {
        gentle: {
          drift: {name: 'Evening Drift', desc: 'Soft, sparse tones to help ease tension.', price: '$30'},
          core: {name: 'Core Resonance (lighter)', desc: 'Reduced intensity with emphasis on breath.', price: '$32'},
          immersion: {name: 'Immersion+ (soft variant)', desc: 'Extended, but gentled layers for longer calm.', price: '$40'}
        },
        medium: {
          drift: {name: 'Evening Drift', desc: 'Balanced layers for an accessible evening session.', price: '$35'},
          core: {name: 'Core Resonance', desc: 'Full resinant layering and gradual climbs.', price: '$45'},
          immersion: {name: 'Immersion+', desc: 'Extended resonance work for deeper release.', price: '$55'}
        },
        intense: {
          drift: {name: 'Evening Drift (dynamic)', desc: 'Bolder presence of tones and focal transitions.', price: '$40'},
          core: {name: 'Core Resonance (intense)', desc: 'Richer low frequencies and stronger crescendos.', price: '$55'},
          immersion: {name: 'Immersion+ (deep)', desc: 'An extended, immersive sound field; longer integration.', price: '$70'}
        }
      };

      function setActive(level){
        mixBtns.forEach(b=>b.classList.toggle('active', b.dataset.level===level));
        updateRecommendation(level, programEl.value);
      }

      mixBtns.forEach(b=>{ b.addEventListener('click',()=> setActive(b.dataset.level)); });

      programEl.addEventListener('change', ()=>{
        const active = document.querySelector('.mix-btn.active').dataset.level;
        updateRecommendation(active, programEl.value);
      });

      function updateRecommendation(level, programKey){
        const p = profiles[level][programKey];
        recName.textContent = p.name;
        recDesc.textContent = p.desc;
        recPrice.textContent = p.price;
      }

      // Initialize
      setActive('medium');

      // Calendar & next-available simulation
      const dates = generateDates(10); // next 10 slots
      const calendar = document.getElementById('calendar');
      const selectDate = document.getElementById('date');
      const nextEl = document.getElementById('next-available');

      function generateDates(n){
        const out = [];
        const now = new Date();
        for(let i=1;i<=n;i++){
          const d = new Date(now.getFullYear(), now.getMonth(), now.getDate()+i, 19, 0, 0);
          out.push(d);
        }
        return out;
      }

      dates.forEach((d,idx)=>{
        const li = document.createElement('li');
        li.textContent = d.toDateString() + ' — 7:00 PM';
        calendar.appendChild(li);
        const opt = document.createElement('option');
        opt.value = d.toISOString();
        opt.textContent = d.toDateString() + ' · 7:00 PM';
        selectDate.appendChild(opt);
      });

      if(dates.length){
        const next = dates[0];
        nextEl.textContent = next.toDateString() + ' at 7:00 PM';
        selectDate.selectedIndex = 0;
      }

      // Simulated submit
      document.getElementById('submit').addEventListener('click', ()=>{
        const name = document.getElementById('name').value.trim();
        const email = document.getElementById('email').value.trim();
        if(!name || !email){ alert('Please provide name and email.'); return; }
        const program = document.getElementById('program').value;
        const date = document.getElementById('date').value;
        alert('Request sent. We will follow up to confirm your reservation.');
        // Reset lightly
        document.getElementById('booking').reset();
        setActive('medium');
      });

    })();
  </script>
</body>
</html>"} 
